const requestInputs={test:{},use:{},live:{}};
let runtime={local:false,available:false,tools:[]},useSamples=false,liveBusy=false,liveError='',liveTimer=null;
const liveRuns=new Map(),liveHistory=new Map();
const steps = ['Purpose','Team','Access','Outputs','Plan','Controls'];
