function clearPlanDrag(){dragState=null;pointerDrag=null;$('app').classList.remove('plan-dragging');for(const element of $('app').querySelectorAll('.over,.drag-source,.tool-drop-over'))element.classList.remove('over','drag-source','tool-drop-over');}
function finishPlanDrop(slot){
  if(!dragState)return;const drag=dragState;clearPlanDrag();
  const next=drag.type==='step'?reorderPlan(draft(),drag.id,slot):insertResource(drag,slot);updatePlan(next,drag.type==='step'?drag.id:next.workflow[slot].id);notify(drag.type==='step'?'Plan order updated.':'Step added to the plan.');
}
function dragAutoScroll(clientY){const canvas=$('app').querySelector('.plan-canvas');if(canvas&&canvas.scrollHeight>canvas.clientHeight){const rect=canvas.getBoundingClientRect();if(clientY<rect.top+60)canvas.scrollTop-=16;else if(clientY>rect.bottom-60)canvas.scrollTop+=16;}else if(clientY<80)window.scrollBy(0,-14);else if(clientY>window.innerHeight-80)window.scrollBy(0,14);}
let skipPlanClickUntil=0;
$('app').addEventListener('input',event=>{if(event.target.dataset.path)updateField(event.target.dataset.path,event.target.value);if(event.target.dataset.requestField){const mode=event.target.dataset.inputMode;requestInputs[mode][currentId]??=mode==='live'?{}:structuredClone((mode==='use'?current().definition:draft()).sample_request?.inputs||{});requestInputs[mode][currentId][event.target.dataset.requestField]=event.target.value;}if(event.target.dataset.request)requests[event.target.dataset.request]=event.target.value;if(event.target.dataset.humanInput)humanDraft[event.target.dataset.humanInput]=event.target.value;if(event.target.hasAttribute('data-assistant-input'))commandState().text=event.target.value;});
$('app').addEventListener('change',event=>{try{if(event.target.hasAttribute('data-live-history')){if(event.target.value)openLiveRun(event.target.value).catch(error=>notify(error.message));return;}if(event.target.dataset.stepParent){const {stepParent:from,stepChild:to}=event.target.dataset;updatePlan(event.target.checked?connectPlanSteps(draft(),from,to):disconnectPlanSteps(draft(),from,to),to);return;}if(event.target.dataset.tool){const role=draft().agents[Number(event.target.dataset.index)],tool=event.target.dataset.tool;if(role.kind==='human')throw new Error('Human members do not use agent tools.');if(event.target.checked&&!role.tools.includes(tool))role.tools.push(tool);else if(!event.target.checked)role.tools=role.tools.filter(t=>t!==tool);markDirty();render();}if(event.target.dataset.format!==undefined)setOutputFormat(Number(event.target.dataset.format),event.target.value);if(event.target.dataset.outputKind!==undefined)setOutputKind(Number(event.target.dataset.outputKind),event.target.value);}catch(error){if(event.target.dataset.stepParent)render();notify(error.message);}});
$('app').addEventListener('click',async event=>{
  const button=event.target.closest('button');if(!button||button.disabled||saving||Date.now()<skipPlanClickUntil)return;
  try{if(button.dataset.select){chooseApplication(button.dataset.select);return;}if(button.dataset.tab){activateTab(button.dataset.tab);$(`tab-${tab}`).focus();return;}if(button.dataset.step!==undefined){buildStep=Number(button.dataset.step);advanced=false;render();return;}if(button.hasAttribute('data-open-plan')){buildStep=4;advanced=false;render();return;}if(button.dataset.newTemplate){openEditor('new',null,button.dataset.newTemplate);return;}if(button.dataset.downloadOutput){downloadResult(button.dataset.downloadOutput);return;}if(button.dataset.record){inspectRecord(button.dataset.record,Number(button.dataset.index));return;}if(button.dataset.activity!==undefined){inspectActivity(Number(button.dataset.activity));return;}if(button.dataset.filter){filters[tab]=button.dataset.filter;render();return;}
    if(button.dataset.connectSource){connectSource=button.dataset.connectSource;render();return;}if(button.dataset.connectTarget){if(!connectSource)throw new Error('Choose a step to connect from.');updatePlan(connectPlanSteps(draft(),connectSource,button.dataset.connectTarget),button.dataset.connectTarget);connectSource=null;render();return;}if(button.dataset.disconnectFrom){updatePlan(disconnectPlanSteps(draft(),button.dataset.disconnectFrom,button.dataset.disconnectTo));return;}if(button.dataset.canvasMode){canvasMode=button.dataset.canvasMode;render();return;}if(button.dataset.canvasZoom){canvasZoom=button.dataset.canvasZoom==='reset'?1:Math.max(.6,Math.min(1.4,canvasZoom+(button.dataset.canvasZoom==='in'?.1:-.1)));render();return;}if(button.dataset.resourcePane){resourcePane=button.dataset.resourcePane;render();return;}
    if(button.dataset.planSelect){showPlanInspector=true;selectedStepId=button.dataset.planSelect;render();const inspector=$('app').querySelector('.workbench-inspector');if(inspector){inspector.scrollTop=0;if(window.innerWidth<1000)inspector.scrollIntoView({behavior:'smooth',block:'start'});}return;}
    if(button.dataset.runStep){selectedRunStepId=button.dataset.runStep;render();return;}
    if(button.dataset.assistantExample){proposeCommand(button.dataset.assistantExample);return;}
    if(button.dataset.planTemplate||button.dataset.planMember||button.dataset.planPreset||button.dataset.planSaved||button.dataset.planTool){addResource(resourceDrag(button));return;}
    if(button.dataset.planMove){movePlanStep(button.dataset.planMove,button.dataset.direction);return;}
    if(button.dataset.planDuplicate){const index=draft().workflow.findIndex(step=>step.id===button.dataset.planDuplicate),next=duplicatePlanStep(draft(),button.dataset.planDuplicate);updatePlan(next,next.workflow[index+1].id);notify('Step duplicated.');return;}
    if(button.dataset.planRemove){updatePlan(removePlanStep(draft(),button.dataset.planRemove));notify('Step removed.');return;}
    const action=button.dataset.action,index=Number(button.dataset.index);
    if(['start-live','cancel-live','submit-live-review','resume-live'].includes(action)){await liveAction(action);return;}if(action==='use-samples'){stopLivePolling();useSamples=true;preview=runs.use;render();return;}if(action==='use-live'){useSamples=false;preview=liveRuns.get(currentId)||null;activateTab('use');return;}if(action==='cancel-connect'){connectSource=null;render();}else if(action==='tidy-canvas'){updatePlan(tidyCanvas(draft()));}else if(action==='toggle-applications'){showAllApplications=!showAllApplications;render();}else if(action==='add-input'){const d=draft();d.inputs??=[];if(d.inputs.length>=12)throw new Error('Use at most 12 fields.');let n=1;while(d.inputs.some(f=>f.id==='field_'+n))n++;d.inputs.push({id:'field_'+n,label:'New field',type:'text',required:false});markDirty();render();}else if(action==='remove-input'){draft().inputs.splice(index,1);markDirty();render();}else if(action==='new')openEditor('goal');else if(action==='import')openEditor('import');else if(action==='save-member')await saveCurrentMember();else if(action==='reload-members')await reloadMembers();else if(action==='isolate-member')isolateSelectedMember();else if(action==='propose-plan')proposeCommand();else if(action==='apply-proposal')applyPlanProposal();else if(action==='discard-proposal'){commandState().proposal=null;commandState().error='';render();}else if(action==='catalogue')openCatalogue();else if(action==='connector-catalogue')openCatalogue('connectors');else if(action==='toggle-plan-resources'){showPlanResources=!showPlanResources;render();}else if(action==='close-plan-inspector'){showPlanInspector=false;render();}else if(action==='tool-catalogue')openCatalogue('tools');else if(['add-role','add-output','remove-role','remove-output'].includes(action))openEditor(action,index);else if(action==='save')await saveApplication();else if(action==='save-use'){await saveApplication();activateTab('use');}else if(action==='export')exportDefinition();else if(action==='advanced'||action==='close-advanced'){advanced=action==='advanced'?!advanced:false;render();}else if(action==='previous-step'){buildStep=Math.max(0,buildStep-1);render();}else if(action==='next-step'){validateDefinition(draft());if(buildStep===steps.length-1)activateTab('test');else{buildStep++;render();}}else if(action==='start-preview')startPreview($(`${tab}-request`).value,tab);else if(action==='pause-preview')pausePreview();else if(action==='step-preview')stepPreview();else if(action==='complete-human')completeHumanCheckpoint();else if(action)mutate(action,index);
  }catch(error){notify(error.message);}
});
$('app').addEventListener('keydown',event=>{if(event.target.dataset.canvasMove&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const id=event.target.dataset.canvasMove,pos=canvasPositions(draft())[id];updatePlan(moveCanvasStep(draft(),id,pos.x+(event.key==='ArrowLeft'?-20:event.key==='ArrowRight'?20:0),pos.y+(event.key==='ArrowUp'?-20:event.key==='ArrowDown'?20:0)),id);return;}
  if(event.target.dataset.planDrag&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();try{movePlanStep(event.target.dataset.planDrag,['ArrowUp','ArrowLeft'].includes(event.key)?'earlier':'later');}catch(error){notify(error.message);}return;}
  if(event.key==='Escape'&&connectSource){connectSource=null;render();return;}if(event.key==='Escape'&&dragState){clearPlanDrag();return;}
  if(event.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const list=['build','test','use'],index=list.indexOf(tab);activateTab(event.key==='Home'?list[0]:event.key==='End'?list[2]:list[(index+(event.key==='ArrowLeft'?2:1))%3]);$(`tab-${tab}`).focus();}
});
$('app').addEventListener('dragstart',event=>{
  const handle=event.target.closest('[data-plan-drag],[data-plan-template],[data-plan-member],[data-plan-preset],[data-plan-saved],[data-plan-tool]');if(!handle||saving)return;
  dragState=resourceDrag(handle);
  event.dataTransfer.effectAllowed=dragState.type==='step'?'move':'copy';event.dataTransfer.setData('text/plain',JSON.stringify(dragState));$('app').classList.add('plan-dragging');handle.closest('[data-plan-node]')?.classList.add('drag-source');
});
function finishToolDrop(target){if(dragState?.type!=='tool')return false;const step=target.closest('[data-plan-tool-target]');if(!step)throw new Error('Drop a tool directly on an AI step or its member settings.');const id=dragState.id;clearPlanDrag();updatePlan(attachPlanTool(draft(),step.dataset.planToolTarget,id),step.dataset.planToolTarget);notify('Tool requested for this step’s member.');return true;}
$('app').addEventListener('dragover',event=>{if(!dragState)return;if(dragState.type==='tool'){const target=event.target.closest('[data-plan-tool-target]');if(!target)return;event.preventDefault();event.dataTransfer.dropEffect='copy';for(const element of $('app').querySelectorAll('.tool-drop-over'))element.classList.remove('tool-drop-over');target.classList.add('tool-drop-over');return;}if(!event.target.closest('.plan-canvas'))return;event.preventDefault();event.dataTransfer.dropEffect=dragState.type==='step'?'move':'copy';highlightPlanSlot(event.target.closest('[data-plan-slot]')?Number(event.target.closest('[data-plan-slot]').dataset.planSlot):planSlotAt(event.clientY));dragAutoScroll(event.clientY);});
$('app').addEventListener('drop',event=>{if(!dragState)return;event.preventDefault();try{if(dragState.type==='tool'){finishToolDrop(event.target);return;}if(!event.target.closest('.plan-canvas')){clearPlanDrag();return;}const slot=event.target.closest('[data-plan-slot]');finishPlanDrop(slot?Number(slot.dataset.planSlot):planSlotAt(event.clientY));}catch(error){clearPlanDrag();notify(error.message);}});
$('app').addEventListener('dragend',clearPlanDrag);
$('app').addEventListener('pointerdown',event=>{
  if(event.target.closest('[data-canvas-move]')||event.pointerType==='mouse'||event.button!==0||saving)return;const handle=event.target.closest('[data-plan-drag],[data-plan-template],[data-plan-member],[data-plan-preset],[data-plan-saved],[data-plan-tool]');if(!handle)return;
  pointerDrag={pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,moved:false,handle,drag:resourceDrag(handle)};handle.setPointerCapture(event.pointerId);
});
$('app').addEventListener('pointermove',event=>{
  if(!pointerDrag||pointerDrag.pointerId!==event.pointerId)return;
  if(!pointerDrag.moved&&Math.hypot(event.clientX-pointerDrag.startX,event.clientY-pointerDrag.startY)>6){pointerDrag.moved=true;dragState=pointerDrag.drag;$('app').classList.add('plan-dragging');pointerDrag.handle.closest('[data-plan-node]')?.classList.add('drag-source');}
  if(pointerDrag.moved){event.preventDefault();if(dragState?.type==='tool'){const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-plan-tool-target]');for(const element of $('app').querySelectorAll('.tool-drop-over'))element.classList.remove('tool-drop-over');target?.classList.add('tool-drop-over');}else highlightPlanSlot(planSlotAt(event.clientY));dragAutoScroll(event.clientY);}
});
$('app').addEventListener('pointerup',event=>{
  if(!pointerDrag||pointerDrag.pointerId!==event.pointerId)return;const moved=pointerDrag.moved;pointerDrag.handle.releasePointerCapture(event.pointerId);
  if(moved){skipPlanClickUntil=Date.now()+400;try{const target=document.elementFromPoint(event.clientX,event.clientY);if(dragState?.type==='tool'){if(!target)throw new Error('Drop a tool on an AI step.');finishToolDrop(target);}else if(target?.closest('.plan-canvas'))finishPlanDrop(planSlotAt(event.clientY));else clearPlanDrag();}catch(error){clearPlanDrag();notify(error.message);}}else clearPlanDrag();
});
$('app').addEventListener('pointercancel',clearPlanDrag);
$('editor-form').addEventListener('input',event=>{if(event.target.dataset.dialogField&&event.target.tagName!=='SELECT')changeDialogField(event.target.dataset.dialogField,event.target.value);});
$('editor-form').addEventListener('change',event=>{if(dialogState?.goalBased&&event.target.dataset.goalRole){const id=event.target.dataset.goalRole;dialogState.roles=event.target.checked?[...new Set([...dialogState.roles,id])]:dialogState.roles.filter(r=>r!==id);if(!event.target.checked)delete dialogState.tools[id];renderEditor();return;}if(dialogState?.goalBased&&event.target.dataset.goalTool){const id=event.target.dataset.goalTool,target=dialogState.toolAgent,list=dialogState.tools[target]||[];dialogState.tools[target]=event.target.checked?[...new Set([...list,id])]:list.filter(t=>t!==id);return;}if(dialogState?.goalBased&&event.target.dataset.goalOutput){const id=event.target.dataset.goalOutput;dialogState.outputs=event.target.checked?[...new Set([...dialogState.outputs,id])]:dialogState.outputs.filter(o=>o!==id);return;}if(dialogState?.kind==='new'&&event.target.dataset.creationRole){const id=event.target.dataset.creationRole;dialogState.roles=event.target.checked?[...new Set([...dialogState.roles,id])]:dialogState.roles.filter(r=>r!==id);if(!event.target.checked)delete dialogState.tools['catalog_'+id];renderEditor();}if(dialogState?.kind==='new'&&event.target.dataset.creationTool){const target=dialogState.toolAgent,id=event.target.dataset.creationTool;const list=dialogState.tools[target]||[];dialogState.tools[target]=event.target.checked?[...new Set([...list,id])]:list.filter(t=>t!==id);}if(event.target.dataset.dialogField&&event.target.tagName==='SELECT')changeDialogField(event.target.dataset.dialogField,event.target.value);});
$('editor-form').addEventListener('click',event=>{const button=event.target.closest('button');if(button?.hasAttribute('data-suggest-from-purpose')){try{const name=dialogState.name;suggestGoalSetup(dialogState.purpose);dialogState.name=name;renderEditor();}catch(error){$('editor-error').textContent=error.message;}return;}if(button?.hasAttribute('data-rethink-goal')){dialogState={kind:'goal',goal:dialogState.goal||''};renderEditor();return;}if(button?.hasAttribute('data-import-review')){try{reviewImport();}catch(error){$('editor-error').textContent=error.message;}}if(button?.hasAttribute('data-dialog-cancel')){$('editor-dialog').close();dialogState=null;}});
$('catalogue-content').addEventListener('click',event=>{const button=event.target.closest('button');if(!button||saving)return;if(button.dataset.catalogueAudience){catalogueAudience=button.dataset.catalogueAudience;openCatalogue('applications');return;}if(button.dataset.catalogueTab){openCatalogue(button.dataset.catalogueTab);return;}if(button.dataset.catalogueConnector){addConnector(button.dataset.catalogueConnector);$('catalogue-dialog').close();buildStep=2;render();return;}if(button.dataset.catalogueCreate){$('catalogue-dialog').close();openEditor('new',null,button.dataset.catalogueCreate);}else if(button.dataset.catalogueTool){$('catalogue-dialog').close();try{openEditor('assign-tool',null,button.dataset.catalogueTool);}catch(error){notify(error.message);}}else if(button.dataset.catalogueBlank){$('catalogue-dialog').close();openEditor('new',null,'blank');}else if(button.dataset.catalogueRole){$('catalogue-dialog').close();openEditor('add-role',null,button.dataset.catalogueRole);}else if(button.dataset.catalogueOutput){$('catalogue-dialog').close();openEditor('add-output',null,button.dataset.catalogueOutput);}});
