function registerTools(){
  if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
  register({name:'read_application_definition',title:'Read application definition',description:'Read the selected application draft and saved version. Does not execute agents.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('No arguments expected.');return {id:currentId,revision:current().revision,definition:structuredClone(draft()),unsaved:dirty()};}});
  register({name:'propose_application_definition',title:'Propose an application change',description:'Present a validated definition change in the plan assistant for the user to review and apply. Does not change the draft, save or execute it.',inputSchema:{type:'object',properties:{definition:{type:'object'},summary:{type:'string',minLength:1,maxLength:1000}},required:['definition','summary'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).some(key=>!['definition','summary'].includes(key))||typeof input.summary!=='string'||!input.summary.trim()||input.summary.length>1000)throw new Error('Provide a definition and bounded change summary.');if(saving)throw new Error('A save is in progress.');validateDefinition(input.definition);const state=commandState();state.error='';state.proposal={prompt:input.summary,base:JSON.stringify(draft()),definition:structuredClone(input.definition),changes:describeDefinitionChanges(draft(),input.definition)};tab='build';buildStep=4;advanced=false;pauseActiveRun();preview=null;render();return {id:currentId,proposed:true,requires_user_apply:true};}});
  register({name:'stage_application_definition',title:'Stage application definition',description:'Replace the selected draft with a validated definition. Does not save or execute it.',inputSchema:{type:'object',properties:{definition:{type:'object'}},required:['definition'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).some(k=>k!=='definition'))throw new Error('Provide a definition.');if(saving)throw new Error('A save is in progress.');validateDefinition(input.definition);drafts.set(currentId,structuredClone(input.definition));activateTab('build');return {id:currentId,staged:true};}});
  register({name:'save_application_definition',title:'Save application definition',description:'Save the selected application draft. Does not execute agents.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('No arguments expected.');if(saving)throw new Error('A save is in progress.');return saveApplication();}});
  register({name:'start_sample_application_preview',title:'Start sample application preview',description:'Test the selected draft using fictional sample results. Does not call a provider or run Conclave.',inputSchema:{type:'object',properties:{task:{type:'string',minLength:1,maxLength:2000}},required:['task'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).some(k=>k!=='task'))throw new Error('Provide a task.');return startPreview(input.task,'test');}});
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
await load();if(currentId)registerTools();


function inputDesignerMarkup(d){return `<section class="panel"><div class="section-head"><h3>Request form</h3><button class="button" data-action="add-input">Add field</button></div><p class="field-help">Choose what people need to fill in when starting a request. Demos keep these answers alongside the results.</p>${(d.inputs||[]).map((f,i)=>`<div class="input-designer">${field('Label',`inputs.${i}.label`,f.label)}<details><summary>Advanced</summary>${field('Field key',`inputs.${i}.id`,f.id)}</details><label>Type<select data-path="inputs.${i}.type">${['text','textarea','number','date'].map(t=>`<option value="${t}" ${t===f.type?'selected':''}>${({text:'Short answer',textarea:'Long answer',number:'Number',date:'Date'})[t]}</option>`).join('')}</select></label><label>Required<select data-path="inputs.${i}.required"><option value="false" ${!f.required?'selected':''}>Optional</option><option value="true" ${f.required?'selected':''}>Required</option></select></label><button class="text-button" data-action="remove-input" data-index="${i}">Remove</button></div>`).join('')}</section>`;}
function generatedRequestMarkup(d,mode){return `<div class="generated-inputs">${(d.inputs||[]).map(f=>{const value=(requestInputs[mode][currentId]||(mode==='live'?{}:d.sample_request?.inputs)||{})[f.id]??'';const attrs=`data-request-field="${escape(f.id)}" data-input-mode="${mode}" id="${mode}-input-${escape(f.id)}" ${f.required?'required':''}`;return `<div class="field"><label for="${mode}-input-${escape(f.id)}">${escape(f.label)}${f.required?' · required':''}</label>${f.type==='textarea'?`<textarea ${attrs} maxlength="2000">${escape(value)}</textarea>`:`<input ${attrs} type="${f.type}" ${f.type==='number'?'step="any"':''} maxlength="2000" value="${escape(value)}">`}</div>`;}).join('')}</div>`;}
function controlsMarkup(d){const warnings=d.budget_warnings||{};return `<div class="step-heading"><div><span class="eyebrow">06 · CONTROLS</span><h2>Limits and approvals</h2><p>Choose when to warn you and when to stop the work.</p></div></div><section class="panel"><h3>Spending and time limits</h3><p class="field-help">Leave a limit blank to skip it. Limits apply to local AI runs. Warnings are not available yet; samples do not enforce limits.</p><div class="budget-grid"><strong>Resource</strong><strong>Warn me</strong><strong>Stop work</strong>${[['tool_calls','Tool uses'],['wall_clock_seconds','Seconds'],['tokens','AI usage (text units)'],['cost_usd','Cost · USD']].map(([key,label])=>`<span>${label}</span>${field('Warning',`budget_warnings.${key}`,warnings[key]??'','number')}${field('Stop work',`run_budget.${key}`,d.run_budget[key]??'','number')}`).join('')}</div></section><section class="panel"><h3>Approvals</h3><p>Add a person’s approval step in the Plan. Changes to files and outgoing messages need approval when tools are connected.</p><p class="field-help">Extra access restrictions can be configured when tools are connected.</p></section><section class="panel"><h3>Check the results</h3><p>Use Test to try the flow and inspect demo results. Made-up results cannot tell you how well the team performs.</p><p class="field-help">Quality scores and comparisons will need real results.</p><button class="button" data-tab="test">Open Test</button></section>`;}
function runInsightsMarkup(d){return `<section class="panel"><div class="section-head"><h3>Request details</h3><span class="demo-pill">DEMO ONLY</span></div><div class="metrics-grid">${['Duration','AI usage','Cost','Tool uses'].map(label=>`<div><strong>${label}</strong><p>Not reported</p></div>`).join('')}</div><p class="field-help">Usage will appear here when AI and tools are connected.</p>${preview?`<details><summary>Request details · ${escape(preview.runId)}</summary><p>${escape(preview.revision?'Saved application version '+preview.revision:'Draft application')}</p><pre>${escape(JSON.stringify(preview.inputs||{},null,2))}</pre></details>`:''}<p class="field-help">Choose a sample, make it your own, then start a request. Each request keeps the version it used.</p></section>`;}

function composeCatalogApplication(templateId,roles=[],tools={}){
  const template=templates.find(t=>t.id===templateId),d=template?structuredClone(template.definition):emptyDefinition();
  for(const id of roles){const role=rolePresets.find(r=>r.id===id);if(!role)throw new Error('Choose a catalog role.');const agentId='catalog_'+id;if(d.agents.some(a=>a.id===agentId))throw new Error('Select each extra role once.');let output=d.state.find(o=>o.type==='records')?.key||d.state[0].key;
    if(role.kind==='human'){output=nextIdentifier('decision',d.state,'key');d.state.push({key:output,label:'Approval decision',kind:'decision',type:'records',merge:'upsert',statuses:['proposed','approved','rejected','changes_requested']});d.views.push({id:nextIdentifier('view',d.views),title:'Approval decision',collection:output,layout:'cards'});}
    d.agents.push({id:agentId,name:role.name,kind:role.kind,role:id,instructions:role.instructions,tools:[]});const step={id:nextIdentifier('stage',d.workflow),name:role.name+' contribution',agent:agentId,task:role.instructions,output};if(role.kind==='human')d.workflow.push(step);else insertWork(d,step);
  }
  for(const [id,selected] of Object.entries(tools)){if(!selected.length)continue;const agent=d.agents.find(a=>a.id===id);if(!agent||agent.kind==='human')throw new Error('Assign tools to an existing AI member.');agent.tools=[...new Set([...agent.tools,...selected])];}
  return validateDefinition(d);
}
function creationCatalogMarkup(s){const d=composeCatalogApplication(s.template,s.roles,s.tools),ai=d.agents.filter(a=>a.kind!=='human');if(!ai.some(a=>a.id===s.toolAgent))s.toolAgent=ai[0]?.id||'';const selected=d.agents.find(a=>a.id===s.toolAgent)?.tools||[];const base=templates.find(t=>t.id===s.template)?.definition||emptyDefinition();
  return `<details class="creation-catalog" data-editor-disclosure="creation-team"><summary>Ready-made roles · add to your team</summary><div class="catalogue-cards">${rolePresets.map(role=>`<label class="access-option"><input type="checkbox" data-creation-role="${role.id}" ${s.roles.includes(role.id)?'checked':''}><span><strong>${escape(role.name)} · ${role.kind==='human'?'Human':'AI'}</strong><small>${escape(role.description)}</small></span></label>`).join('')}</div><p class="field-help">${d.agents.length} members · ${d.workflow.length} plan steps. Each choice adds a team member and a step you can edit.</p></details><details class="creation-catalog" data-editor-disclosure="creation-tools"><summary>Tools · choose what each member can use</summary>${dialogField('Assign tools to','toolAgent',s.toolAgent,'select',ai.map(a=>[a.id,a.name]))}<div class="catalogue-cards">${toolDescriptors.map(tool=>{const included=base.agents.find(a=>a.id===s.toolAgent)?.tools.includes(tool.id);return `<label class="access-option"><input type="checkbox" data-creation-tool="${tool.id}" ${selected.includes(tool.id)?'checked':''} ${included?'disabled':''}><span><strong>${escape(tool.name)}</strong><small>${escape(tool.description)}</small><small>${included?'Included in starter · editable under Access':tool.origin==='bundled'?'Connection needed':'Connection needed'}${['write','send'].includes(tool.permission)?' · approval required':''}</small></span></label>`;}).join('')}</div></details>`;
}
function assignCatalogTool(toolId,agentId){const d=structuredClone(draft()),agent=d.agents.find(a=>a.id===agentId);if(!toolDescriptors.some(t=>t.id===toolId)||!agent||agent.kind==='human')throw new Error('Choose a catalog tool and AI member.');if(!agent.tools.includes(toolId))agent.tools.push(toolId);validateDefinition(d);drafts.set(currentId,d);markDirty();render();notify('Tool assigned. Save the application to keep it.');}

function userApplications(){return applications.filter(a=>!templates.some(t=>t.id===a.id)||a.revision>1);}
function sidebarApplications(){const own=userApplications();if(showAllApplications)return own;const visible=own.slice(0,3),selected=own.find(a=>a.id===currentId);if(selected&&!visible.includes(selected)){if(visible.length===3)visible[2]=selected;else visible.push(selected);}return visible;}
$('app').addEventListener('pointerdown',event=>{const area=event.target.closest('.canvas-viewport');if(!area||event.target.closest('button,input,textarea,select,[data-plan-node]')||event.button!==0)return;canvasPan={area,x:event.clientX,y:event.clientY,left:area.scrollLeft,top:area.scrollTop,pointer:event.pointerId};area.setPointerCapture?.(event.pointerId);area.classList.add('panning');});
$('app').addEventListener('pointermove',event=>{if(!canvasPan||canvasPan.pointer!==event.pointerId)return;canvasPan.area.scrollLeft=canvasPan.left-(event.clientX-canvasPan.x);canvasPan.area.scrollTop=canvasPan.top-(event.clientY-canvasPan.y);});
function endCanvasPan(){if(canvasPan){canvasPan.area.classList.remove('panning');canvasPan.area.releasePointerCapture?.(canvasPan.pointer);canvasPan=null;}}
$('app').addEventListener('pointerup',endCanvasPan);$('app').addEventListener('pointercancel',endCanvasPan);

function recommendGoal(goal){
  if(typeof goal!=='string'||!goal.trim()||goal.length>2000)throw new Error('Describe your goal in up to 2,000 characters.');
  const featuredMatch=[['escalation-preparation',/escalat|handoff/i],['content-repurposing',/repurpos|adapt.*(content|article)|linkedin.*email/i],['case-resolution',/(customer|support|ticket|complaint).*(reply|resolv|refund)|resolv.*(case|ticket)/i],['research-brief',/research.*brief|evidence.*brief/i],['options-comparison',/compare.*options|options.*compar/i],['launch-content-production',/launch.*article|content.*production/i]].find(([,pattern])=>pattern.test(goal));
  const patterns=[['incident-response',/\b(incident|outage|postmortem|on-call)\b/gi],['document-review',/\b(review|proofread|edit|contracts?|proposals?)\b/gi],['due-diligence',/\b(vendors?|suppliers?|due diligence|procurement)\b/gi],['software-delivery',/\b(code|software|patch|bug|test suite|implement)\b/gi],['data-analysis',/\b(data|spreadsheet|csv|statistics|sales|metrics)\b/gi],['content-production',/\b(write|content|article|blog|campaign|newsletter)\b/gi],['support-resolution',/\b(support|customer|ticket|complaint)\b/gi],['project-coordination',/\b(project|milestone|schedule|coordinate|team tasks)\b/gi],['planning-simulation',/\b(simulate|scenario|migration|forecast)\b/gi],['decision-support',/\b(compare|choose|recommend|decision|options)\b/gi],['investigation',/\b(investigate|why|cause|latency|evidence)\b/gi],['research-desk',/\b(research|explore|learn|survey)\b/gi]];
  const scored=patterns.map(([id,pattern])=>({id,score:(goal.match(pattern)||[]).length*(['incident-response','due-diligence','software-delivery','data-analysis','support-resolution','project-coordination','planning-simulation'].includes(id)?3:1)})).sort((a,b)=>b.score-a.score),best=featuredMatch?.[0]||(scored[0].score?scored[0].id:'research-desk'),app=applicationTypes.find(a=>a.id===best),roles=[...new Set(app.members.map(m=>m.preset))],outputs=[...new Set(app.outputs.map(o=>o.kind))];
  if(/\b(report|brief|summary|document)\b/i.test(goal)&&!outputs.includes('document'))outputs.push('document');if(/\b(tasks|action plan|checklist)\b/i.test(goal)&&!outputs.includes('tasks'))outputs.push('tasks');
  const tools={};for(const role of roles){const allowed=rolePresets.find(r=>r.id===role).kind==='human'?[]:role==='researcher'?app.tools.filter(id=>['read','coordinate'].includes(toolDescriptors.find(t=>t.id===id)?.permission)):role==='verifier'?app.tools.filter(id=>['read_file','search_files','web_fetch','calculate','run_tests'].includes(id)):role==='reviewer'&&!roles.includes('researcher')?app.tools.filter(id=>toolDescriptors.find(t=>t.id===id)?.permission==='read'):role==='analyst'?app.tools.filter(id=>['calculate','run_code','read_spreadsheet','query_database'].includes(id)):role==='creator'?app.tools.filter(id=>['generate_artifact','prepare_patch','write_file'].includes(id)):[];tools[role]=app.featured?[...new Set(app.members.filter(m=>m.preset===role).flatMap(m=>m.tools||[]))]:allowed;}
  return {template:best,roles,outputs,tools,reason:scored[0].score?`Suggested from the ${app.name.toLowerCase()} example.`:'No close example found. Start with a general research team and adjust it below.'};
}
function suggestGoalSetup(goal){const recommended=recommendGoal(goal);dialogState={kind:'new',goalBased:true,goal:goal.trim(),name:applicationTypes.find(a=>a.id===recommended.template).name,purpose:goal.trim(),result:'Produce the selected results that answer this goal, with supporting sources and limitations.',...recommended,toolAgent:recommended.roles.find(id=>rolePresets.find(r=>r.id===id).kind!=='human')||''};renderEditor();}
function goalOutputName(id){return ({document:'Written report',findings:'Findings',decision:'Decision',tasks:'Task list',dataset:'Data table',artifact:'Files and links'})[id]||id;}
function goalReviewMarkup(s){const ai=s.roles.filter(id=>rolePresets.find(r=>r.id===id)?.kind!=='human');if(!ai.includes(s.toolAgent))s.toolAgent=ai[0]||'';return `<section class="goal-summary"><p>${escape(s.goal)}</p><button class="text-button" type="button" data-rethink-goal>Change goal</button></section>${dialogField('Name','name',s.name)}<div class="suggested-summary"><div><span class="field-label">Team</span><p>${s.roles.map(id=>escape(rolePresets.find(r=>r.id===id)?.name||id)).join(', ')}</p></div><div><span class="field-label">Results</span><p>${s.outputs.map(goalOutputName).map(escape).join(', ')}</p></div></div><p class="field-help">${escape(s.reason)}</p><details class="quiet-details" data-editor-disclosure="goal-team"><summary>Change team</summary><div class="catalogue-cards">${rolePresets.map(role=>`<label class="access-option"><input type="checkbox" data-goal-role="${role.id}" ${s.roles.includes(role.id)?'checked':''}><span><strong>${escape(role.name)}</strong><small>${escape(role.description)}</small></span></label>`).join('')}</div></details><details class="quiet-details" data-editor-disclosure="goal-results"><summary>Change results</summary><div class="catalogue-cards">${outputTypes.map(o=>`<label class="access-option"><input type="checkbox" data-goal-output="${o.id}" ${s.outputs.includes(o.id)?'checked':''}><span>${escape(goalOutputName(o.id))}</span></label>`).join('')}</div></details><details class="quiet-details" data-editor-disclosure="goal-tools"><summary>Choose tools</summary>${ai.length?`${dialogField('Team member','toolAgent',s.toolAgent,'select',ai.map(id=>[id,rolePresets.find(r=>r.id===id).name]))}<div class="catalogue-cards">${toolDescriptors.map(t=>`<label class="access-option"><input type="checkbox" data-goal-tool="${t.id}" ${(s.tools[s.toolAgent]||[]).includes(t.id)?'checked':''}><span><strong>${escape(t.name)}</strong><small>${escape(t.description)}</small></span></label>`).join('')}</div>`:'<p>Choose an AI team member first.</p>'}</details>`;}

function composeGoalDefinition(s){
  if(!s.name?.trim()||s.name.length>100)throw new Error('Enter an application name of up to 100 characters.');if(!s.roles.length||!s.roles.some(id=>rolePresets.find(r=>r.id===id)?.kind!=='human'))throw new Error('Choose at least one AI team member.');if(!s.outputs.length)throw new Error('Choose at least one result.');
  const starter=applicationTypes.find(a=>a.id===s.template);
  if(starter?.featured&&JSON.stringify([...new Set(starter.members.map(m=>m.preset))].sort())===JSON.stringify([...s.roles].sort())&&JSON.stringify([...new Set(starter.outputs.map(o=>o.kind))].sort())===JSON.stringify([...s.outputs].sort())){const d=structuredClone(templates.find(t=>t.id===s.template).definition);d.name=s.name.trim();d.description=s.goal;for(const a of d.agents){a.instructions+=' Work toward the user goal: '+s.goal;if(a.kind!=='human')a.tools=[...(s.tools[a.role]||[])];}return validateDefinition(d);}
  const d=emptyDefinition();d.name=s.name.trim();d.description=s.goal;d.catalogue_type=s.template;d.inputs=[{id:'context',label:'Context and source references',type:'textarea',required:false}];d.agents=s.roles.map(id=>{const role=rolePresets.find(r=>r.id===id);if(!role)throw new Error('Choose a ready-made role.');return {id,name:role.name,kind:role.kind,role:id,instructions:role.instructions+' Work toward this goal: '+s.goal,tools:role.kind==='human'?[]:[...(s.tools[id]||[])]};});
  d.state=s.outputs.map(id=>{const o=outputTypes.find(o=>o.id===id);if(!o)throw new Error('Choose a supported result.');return {key:id,label:goalOutputName(id),kind:id,type:o.type,merge:o.type==='text'?'replace':'upsert',statuses:[...o.statuses]};});d.views=d.state.map(o=>({id:o.key+'_view',title:o.label,collection:o.key,layout:outputTypes.find(t=>t.id===o.kind).layout}));d.workflow=[];
  const ai=d.agents.filter(a=>a.kind!=='human'),primary=d.state.find(o=>o.type==='records')||d.state[0];
  for(const a of ai){d.workflow.push({id:'work_'+a.id,name:a.name+' contribution',agent:a.id,output:primary.key,task:a.instructions});}
  for(const o of d.state){const preferred=({document:'creator',artifact:'creator',dataset:'analyst',tasks:'coordinator',decision:'analyst',findings:'researcher'})[o.kind],owner=ai.find(a=>a.role===preferred)||ai.at(-1);d.workflow.push({id:'prepare_'+o.key,name:'Prepare '+o.label.toLowerCase(),agent:owner.id,output:o.key,task:'Produce '+o.label.toLowerCase()+' for this goal: '+s.goal+'. Use earlier findings and include supporting sources and limitations.'});}
  for(const a of d.agents.filter(a=>a.kind==='human')){const out=d.state.find(o=>o.kind==='decision')||d.state.at(-1);d.workflow.push({id:'review_'+a.id,name:'Review and approve',agent:a.id,output:out.key,task:'Review the results for this goal: '+s.goal+'. Approve, reject or request changes with a reason.'});}
  return validateDefinition(d);
}

function prunePlanGraph(d){const ids=new Set(d.workflow.map(w=>w.id));if(d.connections!==undefined)d.connections=d.connections.filter(e=>ids.has(e.from)&&ids.has(e.to));if(d.canvas)for(const id of Object.keys(d.canvas.positions))if(!ids.has(id))delete d.canvas.positions[id];}
$('app').addEventListener('pointerdown',event=>{const handle=event.target.closest('[data-canvas-move]');if(!handle||event.button!==0||saving)return;const id=handle.dataset.canvasMove,pos=canvasPositions(draft())[id];canvasNodeDrag={id,handle,pointer:event.pointerId,x:event.clientX,y:event.clientY,start:pos,next:pos,node:handle.closest('[data-plan-node]'),zoom:canvasZoom};handle.setPointerCapture?.(event.pointerId);event.preventDefault?.();});
$('app').addEventListener('pointermove',event=>{const drag=canvasNodeDrag;if(!drag||drag.pointer!==event.pointerId)return;drag.next={x:Math.round(Math.max(0,Math.min(10000,drag.start.x+(event.clientX-drag.x)/drag.zoom))),y:Math.round(Math.max(0,Math.min(10000,drag.start.y+(event.clientY-drag.y)/drag.zoom)))};if(drag.node){drag.node.style.left=drag.next.x+'px';drag.node.style.top=drag.next.y+'px';}const positions={...canvasPositions(draft()),[drag.id]:drag.next};const edges=$('app').querySelector('[data-canvas-edges]');if(edges)edges.innerHTML=canvasEdgePaths(draft(),positions,escape);});
function finishCanvasNode(commit){const drag=canvasNodeDrag;if(!drag)return;canvasNodeDrag=null;drag.handle.releasePointerCapture?.(drag.pointer);if(commit&&JSON.stringify(drag.next)!==JSON.stringify(drag.start)){skipPlanClickUntil=Date.now()+400;updatePlan(moveCanvasStep(draft(),drag.id,drag.next.x,drag.next.y),drag.id);}else render();}
$('app').addEventListener('pointerup',event=>{if(canvasNodeDrag?.pointer===event.pointerId)finishCanvasNode(true);});$('app').addEventListener('pointercancel',event=>{if(canvasNodeDrag?.pointer===event.pointerId)finishCanvasNode(false);});

function addConnector(id){const connector=connectorDescriptors.find(c=>c.id===id);if(!connector)throw new Error('Choose a catalog connector.');const d=structuredClone(draft());d.integrations??=[];if(d.integrations.some(c=>c.connector===id)){notify('That connector is already included.');return;}d.integrations.push({connector:id,purpose:connector.description,scope:'',mode:connector.default_mode});validateDefinition(d);drafts.set(currentId,d);notify('Connector setup added. No account is connected.');}
function connectorSetupMarkup(d){return `<section class="panel"><p class="field-help">Connection setup is planned. Live accounts are unavailable.</p><span class="connection-status">${(d.integrations||[]).length} selected · 0 accounts connected</span>${d.connector_requirements?.length?`<details><summary>Suggested for this workflow</summary><ul>${d.connector_requirements.map(r=>`<li>${escape(r.purpose)} · ${escape(connectorDescriptors.find(c=>c.id===r.suggested)?.name||r.suggested)}${r.required?'':' · optional'}</li>`).join('')}</ul></details>`:''}${(d.integrations||[]).map((item,i)=>{const c=connectorDescriptors.find(c=>c.id===item.connector);if(!c)return '';return `<details class="connector-row quiet-row" data-disclosure="connector-${i}"><summary><strong>${escape(c.name)}</strong><span class="field-help">Not connected</span></summary><div class="row-editor">${field('Use for',`integrations.${i}.purpose`,item.purpose)}${field('Choose service',`integrations.${i}.connector`,item.connector,'select',connectorDescriptors.filter(other=>other.group===c.group).map(other=>[other.id,other.name]))}${field('Allowed sources or destination',`integrations.${i}.scope`,item.scope)}<p class="field-help">Describe the intended folder, queue, project or channel. This does not grant access.</p>${field('Allowed actions',`integrations.${i}.mode`,item.mode,'select',connectorModes(c))}<details><summary>Connection setup</summary><p>Account sign-in, connection tests and credential storage are not implemented. Do not enter passwords or access keys in these fields.</p><button class="button" disabled>Connect account — unavailable</button></details><button class="text-button remove" data-remove-connector="${i}">Remove connection</button></div></details>`;}).join('')||'<p>No connectors selected. Browse the catalog to add sources and destinations.</p>'}<details class="quiet-details" data-disclosure="start-method"><summary>When to run · ${d.start_mode==='event'?'event':d.start_mode==='schedule'?'schedule':'manually'}</summary>${field('Start method','start_mode',d.start_mode||'manual','select',[['manual','Start manually'],['event','When an event arrives — planned'],['schedule','On a schedule — planned']])}<p class="field-help">Only manual sample runs are available. Events and schedules require live connections.</p></details></section>`;}
function connectorModes(c){return c.default_mode==='model'?[['model','Run AI roles']]:c.default_mode==='read'?[['read','Read only']]:[['read','Read only'],['draft','Prepare drafts'],['approved','Take action after approval']];}
$('app').addEventListener('click',event=>{const button=event.target.closest('[data-remove-connector]');if(!button||button.dataset.removeConnector===undefined||saving)return;const d=structuredClone(draft());d.integrations.splice(Number(button.dataset.removeConnector),1);validateDefinition(d);drafts.set(currentId,d);render();});
